<div class="card"><h1>Create Auction Listing</h1><div id="createListingMessage"><?php if($message): ?><div class="alert"><?= $message ?></div><?php endif; ?></div><form id="createListingForm" method="post" enctype="multipart/form-data"><label>Title</label><input name="title" value="<?= e($old['title'] ?? '') ?>"><label>Description</label><textarea name="description"><?= e($old['description'] ?? '') ?></textarea><label>Category</label><select name="category_id"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= (int)($old['category_id'] ?? 0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><label>Condition</label><select name="condition"><?php foreach(['new'=>'New','like_new'=>'Like New','good'=>'Good','fair'=>'Fair'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($old['condition'] ?? 'good')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><label>Starting Price</label><input type="number" step="0.01" name="starting_price" value="<?= e($old['starting_price'] ?? '') ?>"><label>Reserve Price</label><input type="number" step="0.01" name="reserve_price" value="<?= e($old['reserve_price'] ?? '') ?>"><label>End Date/Time</label><input type="datetime-local" name="end_datetime" value="<?= !empty($old['end_datetime']) ? e(date('Y-m-d\\TH:i', strtotime($old['end_datetime']))) : '' ?>"><label>Images up to 5</label><input type="file" name="images[]" multiple accept="image/*"><label><input type="checkbox" name="save_template" value="1" style="width:auto"> Save these listing details as a reusable template</label><button id="createListingButton">Create Listing</button></form></div>
